// Family life & old age (20+): parenting, aging parents, siblings, seniors, last breaths.
import type { EventDef, Life } from '@bl/sim';

// Child-age gates. The engine binds a random living child as actor, so events that name the child
// require EVERY living child to fit the age range; generic ("the baby") events only need one.
const kidAges = (l: Life) => l.npcs.filter((n) => n.role === 'child' && n.alive && !n.temp).map((n) => l.year - n.birthYear);
const anyKid = (min: number, max: number) => (l: Life) => kidAges(l).some((a) => a >= min && a <= max);
const allKids = (min: number, max: number) => (l: Life) => {
  const a = kidAges(l);
  return a.length > 0 && a.every((x) => x >= min && x <= max);
};

